-- ============================================================================
-- CinemaTracker — BRANDED COVERS for the auto-managed "Recs" / "Bucket List"
-- ============================================================================
-- Run this once in the Supabase SQL Editor (idempotent, safe to re-run).
--
-- Previously the Recs / Bucket List cover art was forced in the front end from
-- large local PNGs (assets/icons/*.png), which fetched separately on every
-- render and lagged behind the inline data-URL covers of normal lists. This
-- stores the (downscaled 320px square JPEG) branded covers directly in the DB
-- so they load instantly, exactly like every other list cover.
--
--   • list_cover_defaults  — single source of truth for the two branded covers
--   • backfills Lists.cover for every existing Recs / Bucket List row
--   • new users get the cover automatically (see signup_system.sql, which reads
--     this table when provisioning the two default lists)
--
-- To re-brand later: replace a row's cover here and re-run — the backfill
-- UPDATE re-applies it to every user, and new signups pick it up going forward.
-- ============================================================================

begin;

-- Cover column the Lists overview reads (also created by lists_cover_column.sql).
alter table public."Lists" add column if not exists cover text;

-- Single source of truth for the branded covers (keyed by list name).
create table if not exists public.list_cover_defaults (
  list_name text primary key,
  cover     text not null
);

insert into public.list_cover_defaults (list_name, cover) values
  ('Recs', 'data:image/jpeg;base64,'),
  ('Bucket List', 'data:image/jpeg;base64,')
on conflict (list_name) do update set cover = excluded.cover;

-- Backfill every existing auto-managed list with its branded cover.
update public."Lists" l
set cover = d.cover
from public.list_cover_defaults d
where lower(l.list_name) = lower(d.list_name);

commit;
